// Режим ребёнка QA-B1 → «הורים» и прямой /settings → Parent Gate. Цифры PIN и пароль НЕ вводим.
// ПРОПУЩЕН (решение пользователя 08.11, #8ca267): режим ребёнка теперь на сервере и «запирает» файл входа до PIN/пароля.
// Такой тест может работать только на отдельном слоте QA-B1 (parent-b-auto), а слота parent-b-auto НЕ будет.
// parent-b.json в режим ребёнка НЕ переводить никогда; выход удалением benjico\child-context больше не работает.
// Включить можно только когда появится слот семьи с PIN: убрать test.skip и добавить слот в CHILD_SLOTS (tests/child-slot.helpers.ts).
import { test } from '@playwright/test';
import { ChildSlot, goChildHome, saveSlot, slotState } from '../child-slot.helpers';
import { expectParentGate, expectParentZoneHidden, visibleText } from './session-auth.helpers';

/** Слот QA-B1 — НЕ выдан и не будет (решение 08.11). */
const KID: ChildSlot = { slot: 'parent-b-auto', account: 'parent-b', childId: 'd956324c-5d7c-4837-b9da-324f69570be2', nickname: 'QA-B1' };

test.describe('Сессия и права — режим ребёнка', () => {
  test.skip(true, 'нет слота parent-b-auto — пропущено по решению 08.11');
  test.use({ storageState: slotState(KID), viewport: { width: 1280, height: 800 } });

  test.afterEach(async ({ page }) => {
    await saveSlot(page.context(), KID);
  });

  test('Ребёнок не попадает в зону родителя: «הורים» и прямой /settings → Parent Gate @desktop @data #a337fd', async ({ page }) => {
    await goChildHome(page, KID);

    // 1) Кнопка «הורים» на экране ребёнка (скрин a337fd-childmode-gate: вверху слева, с замком)
    // TODO verify selector: роль кнопки «הורים» (кнопка в шапке или пункт меню) в браузере при записи не проверялась.
    await visibleText(page, 'הורים').click();
    await expectParentGate(page);
    await expectParentZoneHidden(page);

    // 2) Прямой адрес зоны родителя
    await page.goto('/settings');
    await expectParentGate(page);
    await expectParentZoneHidden(page);
  });
});
